@* Displays a single task card with move buttons *@

<div class="task-card">
    <h4>@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    <span class="task-due">@Task.DueDate.ToString("MMM dd")</span>

    <div class="task-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn btn-sm btn-outline" @onclick="OnMoveLeftClick">← Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn btn-sm btn-outline" @onclick="OnMoveRightClick">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }

    private async System.Threading.Tasks.Task OnMoveLeftClick() => await OnMoveLeft.InvokeAsync(Task.Id);
    private async System.Threading.Tasks.Task OnMoveRightClick() => await OnMoveRight.InvokeAsync(Task.Id);
}

@* Inline form for creating a new task within a column *@

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />
    <div class="form-actions">
        <button class="btn btn-primary" @onclick="Save">Save</button>
        <button class="btn btn-secondary" @onclick="Cancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public EventCallback<NewTaskModel> OnSave { get; set; }
    [Parameter, EditorRequired] public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private async Task Save()
    {
        if (string.IsNullOrWhiteSpace(title)) return;
        await OnSave.InvokeAsync(new NewTaskModel(title, assignee, priority, dueDate));
    }

    private async Task Cancel() => await OnCancel.InvokeAsync();

    public record NewTaskModel(string Title, string Assignee, string Priority, DateTime DueDate);
}

@* A single Kanban column displaying tasks and an optional add-task form *@

<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="column-count">@Tasks.Count</span>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="OnMoveLeft"
                      OnMoveRight="OnMoveRight" />
        }
    </div>

    @if (showForm)
    {
        <AddTaskForm OnSave="HandleSave" OnCancel="HideForm" />
    }
    else
    {
        <button class="btn btn-add" @onclick="ShowForm">+ Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = string.Empty;
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
    [Parameter] public EventCallback<AddTaskForm.NewTaskModel> OnTaskAdded { get; set; }

    private bool showForm;

    private void ShowForm() => showForm = true;
    private void HideForm() => showForm = false;

    private async Task HandleSave(AddTaskForm.NewTaskModel model)
    {
        await OnTaskAdded.InvokeAsync(model);
        showForm = false;
    }
}

@* Summary statistics bar for the board *@

<div class="board-stats">
    <span class="stat">Total: <strong>@Total</strong></span>
    <span class="stat">To Do: <strong>@ToDo</strong></span>
    <span class="stat">In Progress: <strong>@InProgress</strong></span>
    <span class="stat">Done: <strong>@DoneCount</strong></span>
    <span class="stat overdue">Overdue: <strong>@Overdue</strong></span>
</div>

@code {
    [Parameter] public int Total { get; set; }
    [Parameter] public int ToDo { get; set; }
    [Parameter] public int InProgress { get; set; }
    [Parameter] public int DoneCount { get; set; }
    [Parameter] public int Overdue { get; set; }
}

@* Search bar for filtering tasks by title *@

<div class="task-search">
    <input type="text" placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> SearchTextChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? string.Empty;
        await SearchTextChanged.InvokeAsync(value);
    }
}

@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Kanban Board</h1>

@if (loading)
{
    <p>Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}
else
{
    <BoardStats Total="allTasks.Count"
                ToDo="todoTasks.Count"
                InProgress="inProgressTasks.Count"
                DoneCount="doneTasks.Count"
                Overdue="allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <TaskSearch SearchText="@searchText" SearchTextChanged="OnSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do"
                      Tasks="filteredTodo"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveRight="MoveToInProgress"
                      OnTaskAdded="model => AddTask(model, \"To Do\")" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="filteredInProgress"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveLeft="MoveToTodo"
                      OnMoveRight="MoveToDone"
                      OnTaskAdded="model => AddTask(model, \"In Progress\")" />

        <KanbanColumn ColumnName="Done"
                      Tasks="filteredDone"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeft="MoveToInProgress2"
                      OnTaskAdded="model => AddTask(model, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool loading = true;
    private string? errorMessage;
    private string searchText = string.Empty;

    private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == "Done").ToList();

    private List<TaskItem> filteredTodo => Filter(todoTasks);
    private List<TaskItem> filteredInProgress => Filter(inProgressTasks);
    private List<TaskItem> filteredDone => Filter(doneTasks);

    private List<TaskItem> Filter(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText)) return tasks;
        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private void OnSearchChanged(string value) => searchText = value;

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.First(t => t.Id == taskId);
            allTasks = allTasks.Select(t => t.Id == taskId ? task with { Status = newStatus } : t).ToList();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private Task MoveToInProgress(int taskId) => MoveTask(taskId, "In Progress");
    private Task MoveToTodo(int taskId) => MoveTask(taskId, "To Do");
    private Task MoveToDone(int taskId) => MoveTask(taskId, "Done");
    private Task MoveToInProgress2(int taskId) => MoveTask(taskId, "In Progress");

    private async Task AddTask(AddTaskForm.NewTaskModel model, string status)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            // CreateTaskAsync may not set the status for the target column, update locally
            allTasks.Add(created with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

